package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;import com.yeyamo_mobile.api.notification_service.domain.DevicePlatform;
@Entity@Table(name="device_push_tokens")public class DevicePushTokenEntity{@Id UUID id;@Column(name="user_id",nullable=false,length=120)String userId;@Column(nullable=false,unique=true,length=500)String token;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)DevicePlatform platform;@Column(name="device_id",nullable=false,length=120)String deviceId;@Column(name="app_version",length=50)String appVersion;@Column(nullable=false)boolean enabled;@Column(name="created_at",nullable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;@Column(name="last_seen_at",nullable=false)Instant lastSeenAt;@Column(name="invalidated_at")Instant invalidatedAt;}
